using Microsoft.Extensions.Logging;
using Microsoft.Agents.AI;

var services = new ServiceCollection();

services.AddLogging(builder => builder
    .AddConsole()
    .SetMinimumLevel(LogLevel.Information));

services.AddChatClient(builder =>
{
    var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
        ?? throw new InvalidOperationException(
            "Set the OPENAI_API_KEY environment variable to run this app.");

    return builder.UseOpenAIChatClient("gpt-4o-mini-2024-07-18", apiKey);
});

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();
var loggerFactory = sp.GetRequiredService<ILoggerFactory>();

// Define tools the agent can use
var notes = new List<(string Title, string Content)>();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(SearchWeb),
    AIFunctionFactory.Create(SaveNote),
    AIFunctionFactory.Create(GetNotes),
};

// Create the research agent
var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    description: "An AI agent that researches topics by searching the web and taking notes.",
    instructions: """
        You are a research assistant. When given a topic:
        1. Search the web for relevant information using multiple queries.
        2. Save important findings as notes with descriptive titles.
        3. After gathering enough information, retrieve all your notes and produce a
           well-structured summary with key findings and sources.
        Be thorough — perform at least 2-3 searches from different angles before summarizing.
        """,
    tools: tools,
    loggerFactory: loggerFactory,
    serviceProvider: sp);

// Get the research topic
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

// Run the agent
var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session: null,
    runOptions: runOptions);

// Print the final response
foreach (var message in response.Messages)
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        Console.WriteLine(message.Text);
    }
}

// --- Tool implementations ---

[Description("Search the web for information on a given query. Returns search results as text.")]
static string SearchWeb(
    [Description("The search query to look up on the web")] string query)
{
    // In production, integrate a real search API (Bing Search, Google Custom Search, etc.)
    Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");
    return $"""
        Search results for "{query}":
        1. Wikipedia summary: {query} is a widely discussed topic with multiple facets
           covering technology, science, and societal impact.
        2. Recent news: Experts highlight new developments in {query} during 2026,
           including breakthroughs in efficiency and scalability.
        3. Research paper: "Advances in {query}" (2025) discusses emerging trends
           and future directions in the field.
        Source: web search results (simulated)
        """;
}

[Description("Save a research note with a title and content for later reference.")]
string SaveNote(
    [Description("A short descriptive title for the note")] string title,
    [Description("The content/body of the note")] string content)
{
    notes.Add((title, content));
    Console.WriteLine($"  [Tool] Saved note: \"{title}\"");
    return $"Note saved successfully: \"{title}\"";
}

[Description("Retrieve all saved research notes to review before writing a summary.")]
string GetNotes()
{
    if (notes.Count == 0)
        return "No notes saved yet.";

    Console.WriteLine($"  [Tool] Retrieving {notes.Count} note(s)");
    return string.Join("\n\n", notes.Select((n, i) =>
        $"--- Note {i + 1}: {n.Title} ---\n{n.Content}"));
}

